+
+    #[test]
+    fn sign_refund_signature_verifies_against_authorizer_address() {
+        let signer = PrivateKeySigner::random();
+        let authorizer_addr = signer.address();
+        let authorizer = ReceiverAuthorizerSigner::new(signer);
